/*
 * Triple-blind cross-check driver for the vendored OpenSSH ed25519.c.
 *
 * SHA-512 constants come from tables.h (generated by gen_tables.py via
 * exact integer Newton roots - no hand transcription). The empty-string
 * digest self-test below transitively validates ALL of H0[8] and K[80]:
 * any single wrong constant changes the digest.
 */
#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include "tables.h"

/* ---- crypto_hash_sha512 entry point (provided by driver) ---- */
int crypto_hash_sha512(unsigned char *out, const unsigned char *in,
    unsigned long long inlen);

int crypto_sign_ed25519_keypair_from_seed(unsigned char *pk,
    unsigned char *sk, const unsigned char *seed);
int crypto_sign_ed25519(unsigned char *sm, unsigned long long *smlen,
    const unsigned char *m, unsigned long long mlen, const unsigned char *sk);
int crypto_sign_ed25519_open(unsigned char *m, unsigned long long *mlen,
    const unsigned char *sm, unsigned long long smlen,
    const unsigned char *pk);

/* ---------------- minimal SHA-512 ---------------- */

typedef struct {
	uint64_t h[8];
	unsigned char buf[128];
	size_t buflen;
	unsigned long long total;
} sha512_ctx;

static uint64_t
rotr(uint64_t v, int n)
{
	return (v >> n) | (v << (64 - n));
}

static void
sha512_init(sha512_ctx *c)
{
	memcpy(c->h, SHA512_H0, sizeof(c->h));
	c->buflen = 0;
	c->total = 0;
}

static void
sha512_block(sha512_ctx *c, const unsigned char *p)
{
	uint64_t w[80];
	int i;
	for (i = 0; i < 16; i++) {
		int j;
		w[i] = 0;
		for (j = 0; j < 8; j++)
			w[i] = (w[i] << 8) | p[i * 8 + j];
	}
	for (i = 16; i < 80; i++) {
		uint64_t s0 = rotr(w[i-15], 1) ^ rotr(w[i-15], 8) ^ (w[i-15] >> 7);
		uint64_t s1 = rotr(w[i-2], 19) ^ rotr(w[i-2], 61) ^ (w[i-2] >> 6);
		w[i] = w[i-16] + s0 + w[i-7] + s1;
	}
	{
		uint64_t a = c->h[0], b = c->h[1], cc = c->h[2], d = c->h[3];
		uint64_t e = c->h[4], f = c->h[5], g = c->h[6], h = c->h[7];
		for (i = 0; i < 80; i++) {
			uint64_t S1 = rotr(e, 14) ^ rotr(e, 18) ^ rotr(e, 41);
			uint64_t ch = (e & f) ^ (~e & g);
			uint64_t t1 = h + S1 + ch + SHA512_K[i] + w[i];
			uint64_t S0 = rotr(a, 28) ^ rotr(a, 34) ^ rotr(a, 39);
			uint64_t maj = (a & b) ^ (a & cc) ^ (b & cc);
			uint64_t t2 = S0 + maj;
			h = g; g = f; f = e; e = d + t1;
			d = cc; cc = b; b = a; a = t1 + t2;
		}
		c->h[0] += a; c->h[1] += b; c->h[2] += cc; c->h[3] += d;
		c->h[4] += e; c->h[5] += f; c->h[6] += g; c->h[7] += h;
	}
}

static void
sha512_update(sha512_ctx *c, const unsigned char *in, size_t len)
{
	c->total += len;
	while (len > 0) {
		size_t take = 128 - c->buflen;
		if (take > len)
			take = len;
		memcpy(c->buf + c->buflen, in, take);
		c->buflen += take;
		in += take;
		len -= take;
		if (c->buflen == 128) {
			sha512_block(c, c->buf);
			c->buflen = 0;
		}
	}
}

static void
sha512_final(sha512_ctx *c, unsigned char out[64])
{
	unsigned long long bits = c->total * 8;
	unsigned char pad = 0x80;
	unsigned char zero = 0;
	unsigned char lenb[16];
	int i, j;
	sha512_update(c, &pad, 1);
	while (c->buflen != 112)
		sha512_update(c, &zero, 1);
	memset(lenb, 0, 16);
	for (i = 0; i < 8; i++)
		lenb[15 - i] = (unsigned char)(bits >> (8 * i));
	sha512_update(c, lenb, 16);
	for (i = 0; i < 8; i++)
		for (j = 0; j < 8; j++)
			out[i * 8 + j] =
			    (unsigned char)(c->h[i] >> (56 - 8 * j));
}

/* Driver-provided hash entry point used by ed25519.c */
int
crypto_hash_sha512(unsigned char *out, const unsigned char *in,
    unsigned long long inlen)
{
	sha512_ctx c;
	sha512_init(&c);
	sha512_update(&c, in, (size_t)inlen);
	sha512_final(&c, out);
	return 0;
}

/* ---------------- hex utils ---------------- */

static const char hexd[] = "0123456789abcdef";

static void
tohex(char *dst, const unsigned char *src, size_t n)
{
	size_t i;
	for (i = 0; i < n; i++) {
		dst[2 * i] = hexd[src[i] >> 4];
		dst[2 * i + 1] = hexd[src[i] & 15];
	}
	dst[2 * n] = 0;
}

static void
fromhex(unsigned char *dst, const char *src, size_t n)
{
	size_t i;
	for (i = 0; i < n; i++) {
		int hi = src[2 * i], lo = src[2 * i + 1];
		hi = (hi >= '0' && hi <= '9') ? hi - '0'
		    : (hi | 32) - 'a' + 10;
		lo = (lo >= '0' && lo <= '9') ? lo - '0'
		    : (lo | 32) - 'a' + 10;
		dst[i] = (unsigned char)((hi << 4) | lo);
	}
}

/* ---------------- RFC 8032 / OpenSSH KAT vectors ---------------- */

struct kat {
	const char *seed_hex;
	const char *pk_hex;
	const char *msg_hex;
	const char *sig_hex;
};

static struct kat kats[] = {
	{ "9d61b19deffd5a60ba844af492ec2cc44449c569"
	  "7b326919703bac031cae7f60",
	    "d75a980182b10ab7d54bfed3c964073a0ee172f3"
	  "daa62325af021a68f707511a",
	    "",
	    "e5564300c360ac729086e2cc806e828a84877f1e"
	  "b8e5d974d873e065224901555fb8821590a33bac"
	  "c61e39701cf9b46bd25bf5f0595bbe2465514143"
	  "8e7a100b" },
	{ "4ccd089b28ff96da9db6c346ec114e0f5b8a319f"
	  "35aba624da8cf6ed4fb8a6fb",
	    "3d4017c3e843895a92b70aa74d1b7ebc9c982ccf"
	  "2ec4968cc0cd55f12af4660c",
	    "72",
	    "92a009a9f0d4cab8720e820b5f642540a2b27b54"
	  "16503f8fb3762223ebdb69da085ac1e43e15996e"
	  "458f3613d0f11d8c387b2eaeb4302aeeb00d2916"
	  "12bb0c00" },
	{ "c5aa8df43f9f837bedb7442f31dcb7b166d38535"
	  "076f094b85ce3a2e0b4458f7",
	    "fc51cd8e6218a1a38da47ed00230f0580816ed13"
	  "ba3303ac5deb911548908025",
	    "af82",
	    "6291d657deec24024827e69c3abe01a30ce548a2"
	  "84743a445e3680d7db5ac3ac18ff9b538d16f290"
	  "ae67f760984dc6594a7c15e9716ed28dc027bece"
	  "ea1ec40a" },
};

int
main(void)
{
	/* --- SHA-512 self test: validates every generated constant --- */
	unsigned char dig[64];
	char hx[129];
	const char *expect_empty =
	    "cf83e1357eefb8bdf1542850d66d8007d620e4050b5715dc83f4a921d36ce9ce"
	    "47d0d13c5d85f2b0ff8318d2877eec2f63b931bd47417a81a538327af927da3e";
	crypto_hash_sha512(dig, (const unsigned char *)"", 0);
	tohex(hx, dig, 64);
	printf("C_sha512_empty_ok=%d\n", strcmp(hx, expect_empty) == 0);

	/* --- Ed25519 KATs --- */
	int all_ok = 1;
	size_t t;
	for (t = 0; t < sizeof(kats) / sizeof(kats[0]); t++) {
		unsigned char seed[32], pk[32], sk[64], msg[128];
		unsigned char sm[256], mo[256];
		unsigned long long smlen, mlen;
		char phex[65], shex[129];
		size_t mlen_in = strlen(kats[t].msg_hex) / 2;

		fromhex(seed, kats[t].seed_hex, 32);
		fromhex(msg, kats[t].msg_hex, mlen_in);

		crypto_sign_ed25519_keypair_from_seed(pk, sk, seed);
		tohex(phex, pk, 32);
		int pk_ok = strcmp(phex, kats[t].pk_hex) == 0;

		crypto_sign_ed25519(sm, &smlen, msg, mlen_in, sk);
		tohex(shex, sm, 64);
		int sig_ok = strcmp(shex, kats[t].sig_hex) == 0;

		int open_ok =
		    crypto_sign_ed25519_open(mo, &mlen, sm, smlen, pk) == 0;

		printf("KAT%zu pk=%d sig=%d open=%d\n",
		    t, pk_ok, sig_ok, open_ok);
		printf("  C_pk =%s\n", phex);
		printf("  C_sig=%s\n", shex);
		all_ok &= pk_ok && sig_ok && open_ok;
	}
	printf("C_ALL_%s\n", all_ok ? "PASS" : "FAIL");
	return all_ok ? 0 : 1;
}
